<?php require __DIR__.'/app/bootstrap.php';$token=(string)($_GET['token']??'');$order=preg_match('/^[a-f0-9]{64}$/D',$token)?query("SELECT id FROM orders WHERE access_token=? AND status='delivered'",[$token])->fetch():false;if(!$order){http_response_code(404);exit('Reviews are available through the private order page after delivery.');}$error='';$saved=false;
$items=query('SELECT DISTINCT product_id,product_name FROM order_items WHERE order_id=?',[$order['id']])->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{submission_limit('reviews');$pid=(int)($_POST['product_id']??0);$rating=(int)($_POST['rating']??0);$name=trim((string)($_POST['display_name']??''));$body=trim((string)($_POST['body']??''));if(!in_array($pid,array_column($items,'product_id'))||$rating<1||$rating>5||strlen($name)<2||strlen($name)>60||strlen($body)<10||strlen($body)>2000||empty($_POST['consent']))throw new DomainException('Choose your purchased product, a rating, a public name and a review of 10–2000 characters. Confirm permission to publish.');if(query('SELECT id FROM reviews WHERE order_id=? AND product_id=?',[$order['id'],$pid])->fetch())throw new DomainException('You have already submitted a review for this product.');$photo=cloud_upload('photo','');query('INSERT INTO reviews(order_id,product_id,display_name,rating,body,photo) VALUES(?,?,?,?,?,?)',[$order['id'],$pid,$name,$rating,$body,$photo?:null]);$saved=true;}catch(DomainException $e){$error=$e->getMessage();}catch(PDOException $e){if($e->getCode()==='23000')$error='You have already submitted a review for this product.';else throw $e;}}
render_header('Review your purchase'); ?>
<main class="page narrow"><h1>Your honest review.</h1><?php if($saved):?><p class="notice">Thank you. Your verified-purchase review is awaiting moderation.</p><?php else:?><?php if($error):?><p class="notice error" role="alert"><?=h($error)?></p><?php endif ?><form method="post" enctype="multipart/form-data"><?=csrf_input()?><label>Purchased product<select name="product_id"><?php foreach($items as $item):?><option value="<?=$item['product_id']?>"><?=h($item['product_name'])?></option><?php endforeach ?></select></label><label>Rating<select name="rating"><?php for($n=5;$n>=1;$n--):?><option value="<?=$n?>"><?=$n?> / 5</option><?php endfor ?></select></label><label>Public display name<input name="display_name" maxlength="60" required placeholder="First name or nickname"></label><label>Your review<textarea name="body" minlength="10" maxlength="2000" required></textarea></label><label>Product photo (optional)<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label><label class="check-label"><input type="checkbox" name="consent" value="1" required><span>I agree to publish my display name, rating, review and optional photo. I own the photo and it contains no private information.</span></label><p>Reviews are checked for spam, personal information and relevance, not for whether the rating is positive.</p><button class="button dark">SUBMIT REVIEW</button></form><?php endif ?></main><?php render_footer(); ?>
